ALTER TABLE claim_comments
  ADD COLUMN section_key     VARCHAR(100)  DEFAULT NULL,
  ADD COLUMN subsection_key  VARCHAR(100)  DEFAULT NULL,
  ADD COLUMN finding_id      VARCHAR(100)  DEFAULT NULL,
  ADD COLUMN pipeline_run_id INT           DEFAULT NULL,
  ADD COLUMN severity        VARCHAR(20)   NOT NULL DEFAULT 'info',
  ADD COLUMN disposition     VARCHAR(30)   DEFAULT NULL,
  ADD COLUMN blocks_approval TINYINT(1)    NOT NULL DEFAULT 0;

CREATE INDEX idx_cc_section ON claim_comments (claim_id, section_key, pipeline_run_id);
CREATE INDEX idx_cc_blocks   ON claim_comments (claim_id, blocks_approval, is_resolved);
